const body = $input.first().json.body ?? {};

if (
  typeof body.message !== 'string' ||
  !body.message.trim() ||
  body.message.length > 2000
) {
  throw new Error('Pergunta inválida.');
}

if (
  typeof body.requestId !== 'string' ||
  typeof body.conversationId !== 'string' ||
  typeof body.architecture !== 'string'
) {
  throw new Error('Identificadores obrigatórios ausentes.');
}

return [{
  json: {
    requestId: body.requestId,
    conversationId: body.conversationId,
    architecture: body.architecture, // ecoado: a interface descarta respostas com valor diferente
    question: body.message.trim(),
    startedAt: Date.now()
  }
}];

const r = $input.first().json;
const v = r.data?.[0]?.embedding;
if (!Array.isArray(v) || v.length !== 1536 || !v.every(Number.isFinite)) throw new Error('Embedding inválido ou dimensão diferente de 1536.');
return [{json:{vector: '[' + v.join(',') + ']', embeddingTokens: r.usage?.total_tokens ?? null}}];

// Busca exata ordenada pelo banco; seleção e expansão sem LLM.
const raw = $input.first().json.documents;
const docs = typeof raw === 'string' ? JSON.parse(raw) : raw;
if (!Array.isArray(docs) || !docs.length) throw new Error('Índice RAG vazio ou modelo incompatível. Execute a indexação.');
const normalize = s => String(s ?? '').normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase();
const type = d => {
  const t = normalize(d.document_type);
  if (['table','tabela'].includes(t)) return 'table';
  if (/relationship|relacionamento|relation|foreign_key/.test(t)) return 'relationship';
  if (/rule|regra/.test(t)) return 'rule';
  if (/overview|visao|general|database|catalog|context|schema|global/.test(t)) return 'overview';
  throw new Error('Tipo de documento não reconhecido: '+d.document_type);
};
const groups = {table:[],relationship:[],rule:[],overview:[]};
for (const d of docs) groups[type(d)].push(d);
if (!groups.table.length || !groups.relationship.length || !groups.rule.length || !groups.overview.length) throw new Error('Índice incompleto: faltam tipos de metadados.');
const ident = '[a-zA-Z_][a-zA-Z0-9_]*';
function tableName(d) {
  const m = typeof d.metadata === 'string' ? JSON.parse(d.metadata) : (d.metadata ?? {});
  const candidates = [m.table, m.table_name, m.tabela, m.nome_tabela, ...(Array.isArray(m.tables) && m.tables.length === 1 ? m.tables : []), ...(Array.isArray(m.tabelas) && m.tabelas.length === 1 ? m.tabelas : []), d.document_id, d.title];
  for (const c of candidates) {
    if (typeof c !== 'string') continue;
    const qualified = c.match(new RegExp('(?:^|[^a-zA-Z0-9_])dataset\\.('+ident+')','i'));
    if (qualified) return qualified[1].toLowerCase();
    const tagged = c.match(new RegExp('^(?:table|tabela)[: /_-]+('+ident+')$','i'));
    if (tagged) return tagged[1].toLowerCase();
    if (c !== d.document_id && c !== d.title && new RegExp('^'+ident+'$').test(c)) return c.toLowerCase();
  }
  throw new Error('Não foi possível identificar a tabela do documento '+d.document_id);
}
const tables = new Map(groups.table.map(d=>[tableName(d),d]));
if (tables.size !== groups.table.length) throw new Error('Documentos de tabela duplicados.');
const escapeRE = s => s.replace(/[.*+?^${}()|[\]\\]/g,'\\$&');
const mentions = (d,n) => new RegExp('(^|[^a-zA-Z0-9_])'+escapeRE(n)+'([^a-zA-Z0-9_]|$)','i').test([d.document_id,d.title,JSON.stringify(d.metadata),d.content].join('\n'));
const graph = new Map([...tables.keys()].map(t=>[t,[]]));
const edges = [];
for (const d of groups.relationship) {
  const raw = [d.document_id,d.title,JSON.stringify(d.metadata),d.content].join(' ');
  const qualified = [...tables.keys()].filter(n=>new RegExp('(^|[^a-zA-Z0-9_])'+escapeRE(n)+'\\.[a-zA-Z_][a-zA-Z0-9_]*','i').test(raw));
  const names = qualified.length === 2 ? qualified : [...tables.keys()].filter(n=>mentions(d,n));
  if (names.length !== 2) throw new Error('Relacionamento sem dois extremos inequívocos: '+d.document_id);
  const [a,b]=names; edges.push({a,b,d}); graph.get(a).push(b); graph.get(b).push(a);
}
for (const adj of graph.values()) adj.sort();
const seeds = groups.table.slice(0,3).map(tableName);
const selected = new Set(seeds);
function path(a,b) {
  const queue=[[a]], seen=new Set([a]);
  for(let i=0;i<queue.length;i++) { const p=queue[i], last=p[p.length-1]; if(last===b)return p; for(const n of graph.get(last)??[]) if(!seen.has(n)){seen.add(n);queue.push([...p,n]);} }
  return [];
}
for(let i=0;i<seeds.length;i++) for(let j=i+1;j<seeds.length;j++) for(const n of path(seeds[i],seeds[j])) selected.add(n);
const tableDocs = [...selected].sort().map(n=>tables.get(n));
const relationshipDocs = edges.filter(e=>selected.has(e.a)&&selected.has(e.b)).map(e=>e.d);
const refs = new Set(tableDocs.flatMap(d=>[...([d.content,JSON.stringify(d.metadata)].join(' ').match(/\bR\d{2,}\b/gi)??[])].map(s=>s.toUpperCase())));
const ruleId = d => [d.document_id,d.title].join(' ').match(/\bR\d{2,}\b/i)?.[0]?.toUpperCase();
const rules = groups.rule.filter((d,i)=>i<3 || refs.has(ruleId(d)));
const chosen = [...groups.overview,...tableDocs,...relationshipDocs,...rules];
const context = chosen.map(d=>`[${d.document_id}] ${d.title}\n${d.content}`).join('\n\n');
return [{json:{retrievalEndedAt:Date.now(),shcemaContext:context,retrieval:{method:'exact_cosine_graph_v1',embeddingModel:'text-embedding-3-small',embeddingTokens:$('Validar embedding').first().json.embeddingTokens,topKTables:3,topKRules:3,seedTables:seeds,selectedTables:[...selected].sort(),documents:chosen.map(d=>({id:d.document_id,type:d.document_type,similarity:d.similarity,hash:d.content_hash})),candidateCount:docs.length,contextCharacters:context.length}}}];

