const r=$input.first().json;
const generationEndedAt=Date.now();   // fim da etapa de geração SQL (resposta da LLM recebida)
const text=(r.output??[]).filter(o=>o.type==='message').flatMap(o=>o.content??[]).find(c=>typeof c.text==='string')?.text;
const usage=r.usage??null;            // tokens informados pela API da OpenAI
const llm={model:r.model??null,usage,generationEndedAt};
let result;
try { result=JSON.parse(text); } catch { result={sql:null,reason:'Resposta do modelo não é JSON válido.'}; }
return [{json:{sql:typeof result?.sql==='string'?result.sql:null,reason:result?.reason??null,...llm}}];

// Barreira conservadora; a role PostgreSQL somente leitura é obrigatória.
const r=$input.first().json;
let sql=r.sql?.trim()??'';
let reason=null;
if(!sql) reason=r.reason??'Modelo não gerou SQL.';
// Remove apenas literais simples e identificadores entre aspas para inspecionar tokens.
// Rejeita escapes e dollar quoting para evitar ambiguidades lexicais.
if(!reason && /\\|\$|--|\/\*/.test(sql)) reason='Sintaxe não permitida pelo validador conservador.';
const masked=sql.replace(/'(?:''|[^'])*'|"(?:""|[^"])*"/g,' ');
const body=masked.trim().replace(/;\s*$/,'');
if(!reason && (!/^(SELECT|WITH)\b/i.test(body)||body.includes(';')||/['"]/.test(body))) reason='Somente uma instrução SELECT ou WITH de leitura é permitida.';
if(!reason && /\b(INSERT|UPDATE|DELETE|MERGE|DROP|ALTER|CREATE|TRUNCATE|GRANT|REVOKE|COPY|CALL|DO|INTO|LOCK|VACUUM|ANALYZE|SET|RESET|EXECUTE|PREPARE|DISCARD|REFRESH|REINDEX|CLUSTER|LISTEN|NOTIFY|UNLISTEN)\b/i.test(body)) reason='Operação não permitida.';
if(!reason && /\b(pg_catalog|information_schema|rag|eval|pg_sleep|pg_read_file|pg_ls_dir|set_config|nextval|setval|dblink\w*|lo_\w+|pg_advisory_\w+)\b/i.test(body)) reason='Acesso ou função não permitida.';
return [{json:{...r,sql:sql||null,valid:!reason,validationError:reason}}];

let emb=null, ctx=null, g=null;
try { emb=$('Validar embedding').first(0)?.json ?? null; } catch {}
try { ctx=$('Montar contexto recuperado').first(0)?.json ?? null; } catch {}
try { g=$('Extrai sql').first(0)?.json ?? null; } catch {}
function metricas({startedAt, emb, embeddingUsed, ctx, llmCalled, g}) {
  const u=g?.usage??null;
  const llmInput = llmCalled ? (u?.input_tokens ?? null) : 0;
  const llmOutput = llmCalled ? (u?.output_tokens ?? null) : 0;
  const llmReasoning = llmCalled ? (u?.output_tokens_details?.reasoning_tokens ?? null) : 0;
  const embedding = !embeddingUsed ? 0 : (emb?.embeddingTokens ?? null);
  const parts=[llmInput,llmOutput,embedding];
  const total = parts.some(x=>x===null) ? null : parts.reduce((a,b)=>a+b,0);
  const contextReadyAt = ctx ? ctx.retrievalEndedAt : startedAt;   // A: contexto fixo, pronto no início
  return {
    model: g?.model ?? null,
    usage: u,
    tokens: {llmInput, llmOutput, llmReasoning, embedding, total},
    stageTimingsMs: {
      retrieval: ctx?.retrievalEndedAt ? ctx.retrievalEndedAt - startedAt : null,
      generation: (g?.generationEndedAt && contextReadyAt) ? g.generationEndedAt - contextReadyAt : null,
    },
  };
}
const entrada=$('Preparar entrada').first().json;
const geracao=$('Extrai sql').first().json;
const retrieval=$('Montar contexto recuperado').first().json.retrieval;
const resultados=$input.all().map(i=>i.json).filter(r=>Object.keys(r).length>0);
const columns=resultados.length?Object.keys(resultados[0]):[];
return [{json:{requestId:entrada.requestId,conversationId:entrada.conversationId,architecture:entrada.architecture,status:'completed',message:resultados.length?`Consulta executada com sucesso. ${resultados.length} registro(s) retornado(s).`:'Consulta executada com sucesso, mas nenhum registro foi encontrado.',data:{columns,rows:resultados.map(r=>columns.map(c=>r[c]??null))},metadata:{executionTimeMs:Date.now()-entrada.startedAt,attempts:1,sql:geracao.sql,contextUsed:(retrieval?.documents??[]).map(d=>String(d.id)),retrieval,...metricas({startedAt:entrada.startedAt,emb,embeddingUsed:true,ctx,llmCalled:true,g})}}}];

const e=$('Preparar entrada').first().json;
const item=$input.first().json;
// first(0): lê a saída PRINCIPAL. Estes nós também se ligam a este pela saída de erro (1), e sem o
// índice o n8n lê justamente essa saída (vazia), devolvendo undefined mesmo com o nó executado.
let emb=null, ctx=null, g=null;
try { emb=$('Validar embedding').first(0)?.json ?? null; } catch {}
try { ctx=$('Montar contexto recuperado').first(0)?.json ?? null; } catch {}
try { g=$('Extrai sql').first(0)?.json ?? null; } catch {}
function metricas({startedAt, emb, embeddingUsed, ctx, llmCalled, g}) {
  const u=g?.usage??null;
  const llmInput = llmCalled ? (u?.input_tokens ?? null) : 0;
  const llmOutput = llmCalled ? (u?.output_tokens ?? null) : 0;
  const llmReasoning = llmCalled ? (u?.output_tokens_details?.reasoning_tokens ?? null) : 0;
  const embedding = !embeddingUsed ? 0 : (emb?.embeddingTokens ?? null);
  const parts=[llmInput,llmOutput,embedding];
  const total = parts.some(x=>x===null) ? null : parts.reduce((a,b)=>a+b,0);
  const contextReadyAt = ctx ? ctx.retrievalEndedAt : startedAt;   // A: contexto fixo, pronto no início
  return {
    model: g?.model ?? null,
    usage: u,
    tokens: {llmInput, llmOutput, llmReasoning, embedding, total},
    stageTimingsMs: {
      retrieval: ctx?.retrievalEndedAt ? ctx.retrievalEndedAt - startedAt : null,
      generation: (g?.generationEndedAt && contextReadyAt) ? g.generationEndedAt - contextReadyAt : null,
    },
  };
}
const message=String(item.validationError??item.error?.message??(typeof item.error==='string'?item.error:null)??item.message??'Falha na recuperação, geração ou execução.');
// Etapa em que a falha ocorreu (para análise em eval.run.error_code)
const code = !ctx ? 'RETRIEVAL_FAILED'
  : !g ? 'LLM_ERROR'
  : !g.sql ? 'SQL_GENERATION_FAILED'
  : item.validationError ? 'SQL_VALIDATION_FAILED'
  : 'SQL_EXECUTION_FAILED';
const retrieval=ctx?.retrieval??null;
// a LLM só é chamada depois do contexto montado; se ctx existe e g não, ela falhou (tokens desconhecidos)
const metadata={executionTimeMs:Date.now()-e.startedAt,attempts:g?1:0,retrieval,...metricas({startedAt:e.startedAt,emb,embeddingUsed:true,ctx,llmCalled:!!ctx,g})};
if (typeof g?.sql==='string' && g.sql) metadata.sql=g.sql;               // contrato: sql deve ser string
if (retrieval) metadata.contextUsed=(retrieval.documents??[]).map(d=>String(d.id));
return [{json:{requestId:e.requestId,conversationId:e.conversationId,architecture:e.architecture,status:'error',message,
  error:{code,retryable:code==='RETRIEVAL_FAILED'||code==='LLM_ERROR',details:message.slice(0,2000)},metadata}}];
